/** Explicit technical lessons keyed by the canonical investigation IDs.
 * Columns: mechanism | native read-only observation | guided comparison | conclusion.
 * These observations are instructions, never executed by the reader.
 */
export interface InvestigationDetail { mechanism: string; observation: string; experiment: string; conclusion: string }
export const INVESTIGATION_DETAILS: Record<string, InvestigationDetail> = {};
function add(rows: string) {
  for (const row of rows.trim().split('\n')) {
    const [id, mechanism, observation, experiment, conclusion] = row.split('|').map(part => part.trim());
    if (!id || !mechanism || !observation || !experiment || !conclusion || INVESTIGATION_DETAILS[id]) throw new Error(`Invalid investigation lesson: ${id}`);
    INVESTIGATION_DETAILS[id] = { mechanism, observation, experiment, conclusion };
  }
}
